def find_duplicate(nums):
    slow = fast = nums[0]
    while True:
        slow = nums[slow]
        fast = nums[nums[fast]]
        if slow == fast:
            break
    slow = nums[0]
    while slow != fast:
        slow, fast = nums[slow], nums[fast]
    return slow

def majority(nums):
    cand, count = None, 0
    for n in nums:
        if count == 0:
            cand = n
        count += 1 if n == cand else -1
    return cand

